INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (194, 'publicarModeloVersao', 'Grava um snapshot do estado atual das linhas do modelo (DRIVER_FORMULA) como nova versao no historico. Params: driverId, agora. Autor = usuario logado (:VAR_USER).', 'SQL', 'INSERT INTO DRIVER_VERSAO (DRIVER_ID, NUMERO, SNAPSHOT, CRIADO_EM, CRIADO_POR)
SELECT
  {{driverId}},
  (SELECT COALESCE(MAX(NUMERO),0)+1 FROM (SELECT NUMERO FROM DRIVER_VERSAO WHERE DRIVER_ID = {{driverId}}) x),
  (SELECT JSON_ARRAYAGG(JSON_OBJECT(''CODIGO'',f.CODIGO,''NOME_CUSTOM'',f.NOME_CUSTOM,''CONTA_ID'',f.CONTA_ID,''TIPO'',f.TIPO,''FORMULA'',f.FORMULA,''ORDEM'',f.ORDEM,''ESCONDER'',f.ESCONDER,''NEGRITO'',f.NEGRITO,''FORMATO'',f.FORMATO)) FROM DRIVER_FORMULA f WHERE f.DRIVER_ID = {{driverId}}),
  ''{{agora}}'',
  :VAR_USER', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
